{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group allows unrestricted ingress",
      "resource": "aws_security_group.lb",
      "severity": "CRITICAL",
      "explanation": "The security group allows unrestricted ingress (0.0.0.0/0) on all ports and protocols, which exposes the resource to the entire internet and increases the risk of unauthorized access."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Security group allows unrestricted egress",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group allows unrestricted egress (0.0.0.0/0) on all ports and protocols, which could allow unintended data exfiltration or communication with malicious hosts."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n\n  egress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}",
  "fix_summary": "Restricted ingress and egress rules to allow only HTTPS (port 443) traffic, reducing the risk of unauthorized access and data exfiltration while maintaining necessary functionality."
}
